-- The outbox table from part one, plus the columns that retry and monitoring need.
-- PostgreSQL 18: uuidv7() is built in, so event ids are generated by the database and sort by time.

CREATE TABLE outbox (
    id                   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    event_id             UUID        NOT NULL DEFAULT uuidv7() UNIQUE,
    aggregate_id         TEXT        NOT NULL,
    event_type           TEXT        NOT NULL,
    payload              JSONB       NOT NULL,
    status               TEXT        NOT NULL DEFAULT 'pending'
                         CHECK (status IN ('pending', 'published', 'dead')),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- Retry state. attempts counts claims, not failures: a relay that dies mid-publish never
    -- reaches its catch block, and the attempt still has to count.
    attempts             INT         NOT NULL DEFAULT 0,
    -- Attempts that told us nothing: the relay never came back (lease expired), or it came back
    -- with an exception nobody classified. Small limit, then dead.
    unexplained_failures INT         NOT NULL DEFAULT 0,
    -- Start of the retry window: the first failure, not the insert. An event that waited a day
    -- behind a stopped relay has not been failing for a day. NULL until something fails, and
    -- NULL again after a requeue.
    retry_since          TIMESTAMPTZ,
    next_attempt_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_error           TEXT,

    -- The lease. A claim is a short committed UPDATE, not a row lock held across the network call.
    locked_by            TEXT,
    locked_until         TIMESTAMPTZ,

    published_at         TIMESTAMPTZ,
    dead_at              TIMESTAMPTZ
);

-- The relay's hot path: rows that can still be claimed, in the order they are due.
CREATE INDEX outbox_due ON outbox (next_attempt_at, id) WHERE status = 'pending';

-- Everything not yet published, per aggregate: the ordering check and the health query read this,
-- and neither has to touch the published history.
CREATE INDEX outbox_unpublished ON outbox (aggregate_id, id) WHERE status <> 'published';

-- One row per relay: its heartbeat and its counters. Each relay writes only its own row, so the
-- counters add no contention between relays; the exporter sums them.
CREATE TABLE outbox_relay (
    relay_id      TEXT        PRIMARY KEY,
    beat_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    published     BIGINT      NOT NULL DEFAULT 0,
    retried       BIGINT      NOT NULL DEFAULT 0,
    dead_lettered BIGINT      NOT NULL DEFAULT 0,
    lease_lost    BIGINT      NOT NULL DEFAULT 0
);
